-- Test-only operational function snapshot captured by admin SELECT 2026-10-15. Never deploy this fixture.
CREATE OR REPLACE FUNCTION public.notification_reservation(reservation_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ declare result jsonb; begin if not private.is_active_member() then raise exception 'membership_required';end if; select jsonb_build_object('id',c.id,'state',c.state,'preferred_at',c.preferred_at,'office_name',o.name,'journey_state',c.journey_state,'workspace',case when c.customer_id=auth.uid() then '/requests.html' when c.planner_id=auth.uid() then '/partner-work.html' when private.is_admin() then '/admin-requests.html' else null end) into result from private.consultations c left join private.office_locations o on o.id=c.office_id where c.id=reservation_id and (c.customer_id=auth.uid() or c.planner_id=auth.uid() or private.is_admin() or exists(select 1 from private.office_staff s where s.office_id=c.office_id and s.user_id=auth.uid())); if result is null then raise exception 'reservation_not_found';end if;return result; end$function$;
CREATE OR REPLACE FUNCTION public.notification_inbox(operation text DEFAULT 'list'::text, notification_id uuid DEFAULT NULL::uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ begin if not private.is_active_member() then raise exception 'membership_required';end if; if operation='read' then update private.notifications set read_at=coalesce(read_at,now()),delivery_status='READ',updated_at=now() where id=notification_id and recipient_user_id=auth.uid(); elsif operation='read_all' then update private.notifications set read_at=now(),delivery_status='READ',updated_at=now() where recipient_user_id=auth.uid() and read_at is null; elsif operation<>'list' then raise exception 'invalid_operation';end if; return jsonb_build_object('unread',(select count(*) from private.notifications where recipient_user_id=auth.uid() and read_at is null),'items',(select coalesce(jsonb_agg(to_jsonb(n) order by created_at desc),'[]') from (select id,notification_type,title,body,deep_link,read_at,created_at from private.notifications where recipient_user_id=auth.uid() order by created_at desc limit 100) n)); end$function$;
CREATE OR REPLACE FUNCTION private.reservation_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ declare event_type text;heading text;description text:='약속한 일정을 확인해주세요.';recipient uuid;receivers uuid[];target text; begin select * into new from private.consultations where id=new.id; if tg_op='INSERT' then event_type:=case when new.office_id is not null then 'OFFICE_BOOKING_REQUESTED' else 'RESERVATION_REQUESTED' end;heading:=case when new.office_id is not null then '새 방문예약 요청이 도착했어요.' else '새 상담 요청이 도착했어요.' end;description:='가능한 일정인지 확인해주세요.'; if new.planner_id is not null then receivers:=array[new.planner_id];else select array_agg(user_id) into receivers from private.office_staff where office_id=new.office_id;if receivers is null then select array_agg(user_id) into receivers from private.admin_memberships;end if;end if; else if new.state is not distinct from old.state and new.preferred_at is not distinct from old.preferred_at and new.planner_id is not distinct from old.planner_id and new.journey_state is not distinct from old.journey_state and new.planner_ok is not distinct from old.planner_ok then return new;end if; receivers:=array[new.customer_id,new.planner_id]; if new.journey_state is distinct from old.journey_state and new.journey_state in ('departed','arrived') then event_type:=case when new.journey_state='departed' then 'EXPERT_DEPARTED' else 'EXPERT_ARRIVED' end;heading:=case when new.journey_state='departed' then '전문가가 출발했어요.' else '전문가가 도착했어요.' end;receivers:=array[new.customer_id]; elsif new.state='cancelled' then event_type:=case when new.office_id is not null then 'OFFICE_BOOKING_CANCELLED' else 'RESERVATION_CANCELLED' end;heading:='예약이 취소됐어요.'; elsif new.state='completed' then event_type:='RESERVATION_COMPLETED';heading:='상담이 완료됐어요.'; elsif new.state in ('confirmed','scheduled') and old.state not in ('confirmed','scheduled') then event_type:=case when new.office_id is not null then 'OFFICE_BOOKING_CONFIRMED' else 'RESERVATION_ACCEPTED' end;heading:=case when new.office_id is not null then '보험소 방문예약이 확정됐어요.' else '예약이 확정됐어요.' end; elsif new.state='unmatched' then event_type:='RESERVATION_REJECTED';heading:='해당 일정으로 예약이 어려워요.';description:='다른 전문가나 시간을 확인해주세요.'; elsif new.preferred_at is distinct from old.preferred_at then event_type:='RESERVATION_CHANGED';heading:='예약시간이 변경됐어요.'; elsif new.planner_id is distinct from old.planner_id then event_type:='RESERVATION_REQUESTED';heading:='담당 예약이 배정됐어요.';receivers:=array[new.planner_id]; elsif new.planner_ok and not old.planner_ok then event_type:='RESERVATION_ACCEPTED';heading:='전문가가 요청을 확인했어요.';description:='내 예약에서 최종 일정을 확인해주세요.';receivers:=array[new.customer_id]; else event_type:='RESERVATION_CHANGED';heading:='예약 진행상황이 변경됐어요.';end if; if new.office_id is not null then receivers:=receivers||coalesce((select array_agg(user_id) from private.office_staff where office_id=new.office_id),array[]::uuid[]);end if; end if; foreach recipient in array coalesce(receivers,array[]::uuid[]) loop if recipient is null or recipient=auth.uid() then continue;end if; target:=case when recipient=new.customer_id then '/requests.html' when exists(select 1 from private.admin_memberships where user_id=recipient) then '/admin-requests.html' else '/partner-work.html' end; insert into private.notifications(recipient_user_id,notification_type,title,body,consultation_id,insurance_office_id,deep_link,dedupe_key) values(recipient,event_type,heading,description,new.id,new.office_id,'/notifications.html?reservation='||new.id::text,'reservation:'||new.id::text||':'||event_type||':'||new.revision::text) on conflict do nothing; end loop; return new; end$function$;
